create extension if not exists btree_gist;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now());
create table if not exists public.facilities(id uuid primary key default gen_random_uuid(),name text not null,address text,timezone text not null default 'Asia/Manila',is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.booking_settings(id uuid primary key default gen_random_uuid(),facility_id uuid not null references public.facilities(id) on delete cascade,hourly_rate integer not null default 450,currency text not null default 'PHP',opening_time time not null default '16:00',closing_time time not null default '03:00',slot_duration_minutes integer not null default 60,hold_duration_minutes integer not null default 15,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table if not exists public.courts(id uuid primary key default gen_random_uuid(),facility_id uuid not null references public.facilities(id) on delete cascade,name text not null,description text,image_url text,features text[] not null default '{}',is_active boolean not null default true,display_order integer not null default 0,created_at timestamptz not null default now());
do $$ begin create type public.booking_status as enum('pending_payment','confirmed','cancelled','expired'); exception when duplicate_object then null; end $$;
do $$ begin create type public.payment_status as enum('pending','paid','failed','cancelled','refund_pending','refunded'); exception when duplicate_object then null; end $$;
create table if not exists public.bookings(id uuid primary key default gen_random_uuid(),booking_reference text not null unique,user_id uuid not null references auth.users(id) on delete restrict,court_id uuid not null references public.courts(id) on delete restrict,start_at timestamptz not null,end_at timestamptz not null,status public.booking_status not null default 'pending_payment',total_amount integer not null,currency text not null default 'PHP',hold_expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint booking_valid_range check(end_at>start_at));
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),booking_id uuid not null unique references public.bookings(id) on delete cascade,provider text not null default 'paymongo',provider_checkout_id text,provider_payment_id text,amount integer not null,currency text not null default 'PHP',status public.payment_status not null default 'pending',idempotency_key text,provider_event_id text unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.blocked_times(id uuid primary key default gen_random_uuid(),court_id uuid references public.courts(id) on delete cascade,start_at timestamptz not null,end_at timestamptz not null,reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.admin_audit_log(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,entity_type text,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
insert into public.facilities(name,address) select 'Golden Hour Courts','Cebu, Philippines' where not exists(select 1 from public.facilities);
insert into public.booking_settings(facility_id) select id from public.facilities where not exists(select 1 from public.booking_settings where booking_settings.facility_id=facilities.id);
insert into public.courts(facility_id,name,description,features,display_order) select f.id,'Court '||n,'Premium pickleball court.',array['LED lighting','Tournament lines','Paddle-ready'],n from public.facilities f cross join generate_series(1,5)n where not exists(select 1 from public.courts c where c.facility_id=f.id);
create index if not exists bookings_court_start_idx on public.bookings(court_id,start_at);create index if not exists bookings_user_idx on public.bookings(user_id);